from collections import deque
from itertools import combinations, permutations
import random

def bfs(adj, s):
    d = {s: 0}; q = deque([s])
    while q:
        x = q.popleft()
        for y in adj[x]:
            if y not in d: d[y] = d[x] + 1; q.append(y)
    return d

def dfs_classify(adj, s):
    # CLRS-style DFS; an undirected edge is classified when first scanned
    color = {v: 'W' for v in adj}; t = [0]; disc = {}; first = {}; kind = {}
    def visit(x):
        color[x] = 'G'; t[0] += 1; disc[x] = t[0]
        for y in adj[x]:
            e = frozenset((x, y))
            if e not in kind:
                first[e] = (x, y)
                kind[e] = {'W': 'tree', 'G': 'back', 'B': 'forward/cross'}[color[y]]
                if color[y] == 'W': visit(y)
        color[x] = 'B'
    visit(s)
    return first, kind, disc

# 1) The explicit counterexample
adj = {'s': ['a', 'u'], 'a': ['s', 'v'], 'v': ['a', 'w', 'u'], 'w': ['v', 'u'], 'u': ['s', 'w', 'v']}
d = bfs(adj, 's'); first, kind, disc = dfs_classify(adj, 's')
e = frozenset(('u', 'v'))
print('d =', d)
print('edge (u,v): first explored', first[e], '->', kind[e])   # ('u','v') -> back, with d[u]=1 < d[v]=2

# 2) Random search: which classes occur for edges with d[x]<d[y] first explored x->y?
random.seed(0)
seen_bfs, seen_disc = set(), set()
for _ in range(20000):
    n = random.randint(2, 7); V = list(range(n))
    E = [p for p in combinations(V, 2) if random.random() < 0.5]
    adj = {v: [] for v in V}
    for a, b in E: adj[a].append(b); adj[b].append(a)
    for v in V: random.shuffle(adj[v])
    d = bfs(adj, 0); first, kind, disc = dfs_classify(adj, 0)
    for e, (x, y) in first.items():
        if d[x] < d[y]: seen_bfs.add(kind[e])
        if disc[x] < disc[y]: seen_disc.add(kind[e])
print('d = shortest-path length :', sorted(seen_bfs))   # ['back', 'tree'] -> not forced
print('d = DFS discovery time   :', sorted(seen_disc))  # ['tree'] only

# 3) Exhaustive check that 4 vertices cannot give a counterexample (all graphs, all adjacency orders)
from itertools import product
def exhaustive(n):
    V = range(n); E = list(combinations(V, 2))
    for m in range(1, 1 << len(E)):
        adj = {v: [] for v in V}
        for i, (a, b) in enumerate(E):
            if m >> i & 1: adj[a].append(b); adj[b].append(a)
        d = bfs(adj, 0)
        for orders in product(*[list(permutations(adj[v])) for v in V]):
            first, kind, _ = dfs_classify({v: list(orders[v]) for v in V}, 0)
            if any(d[x] < d[y] and kind[e] == 'back' for e, (x, y) in first.items()): return True
    return False
print('back edge possible with 4 vertices:', exhaustive(4))   # False -> 5 vertices is the minimum
